{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError('case must be dict')
    for key in ['items', 'required_failure_items', 'unresolved_without']:
        if key not in case:
            raise ValueError(f'Missing field {key}')
    items = case['items']
    required = case['required_failure_items']
    unresolved_without = case['unresolved_without']
    if not isinstance(items, list) or not all(isinstance(x, str) for x in items):
        raise ValueError('items must be list of strings')
    if not isinstance(required, list) or not all(isinstance(x, str) for x in required):
        raise ValueError('required_failure_items must be list of strings')
    if not isinstance(unresolved_without, list) or not all(isinstance(x, str) for x in unresolved_without):
        raise ValueError('unresolved_without must be list of strings')
    if not set(required).issubset(set(items)):
        raise ValueError('required_failure_items not subset of items')
    if not set(unresolved_without).issubset(set(items)):
        raise ValueError('unresolved_without not subset of items')

    def test(subset):
        s = set(subset)
        if set(required).issubset(s):
            return 'FAIL'
        for item in unresolved_without:
            if item not in s:
                return 'UNRESOLVED'
        return 'PASS'

    config = items.copy()
    if test(config) != 'FAIL':
        raise ValueError('Initial configuration does not produce FAIL')
    test_count = 1
    n = 2
    while len(config) > 1:
        part_size = (len(config) + n - 1) // n
        parts = [config[i:i+part_size] for i in range(0, len(config), part_size)]
        found_fail = False
        for part in parts:
            result = test(part)
            test_count += 1
            if result == 'FAIL':
                config = part
                found_fail = True
                break
        if found_fail:
            n = 2
            continue
        for part in parts:
            complement = [x for x in config if x not in part]
            result = test(complement)
            test_count += 1
            if result == 'FAIL':
                config = complement
                found_fail = True
                break
        if found_fail:
            n = 2
            continue
        n = min(2 * n, len(config))
        if n == len(config):
            break

    return {
        'minimal_failure': config,
        'outcome': 'FAIL',
        'tests': test_count
    }
"}
